		"leaderless_observed":                 leaderless > 0,
		"leaderless_first_ms":                 leaderlessFirst,
		"leaderless_last_ms":                  leaderlessLast,
		"old_leader_down_samples":             oldLeaderDown,
		"old_leader_lost_leadership_observed": oldLeaderDown > 0,
		"target_is_leader_at_endpoint":        target.raft.State() == Leader,
