	// strand that VerifyLeader shows with its always-buffered verifyCh.
	for trial := 0; trial < 3; trial++ {
		assuranceRunShutdownTrial(t, trial, "barrier", true, true)
		assuranceRunShutdownTrial(t, trial, "apply", true, true)
	}
}

