		"event":               "assurance_transfer_target",
		"case":                caseName,
		"leader_id":           string(leader.id),
		"target_id":           string(target.id),
		"target_is_nonvoter":  useNonvoter,
		"target_suffrage":     targetSuffrage,
		"target_state_before": target.raft.State().String(),
		"leader_term_before":  leaderTermBefore,
		"voters":              voterIDs,
		"voter_count":         len(voterIDs),
		"nonvoters":           nonvoterIDs,
		"election_timeout":    leader.raft.config().ElectionTimeout.String(),
		"pre_vote_default":    !leader.raft.preVoteDisabled,
	})

	callAt := time.Now()
	future := leader.raft.LeadershipTransferToServer(target.id, target.addr)

	// Sample leadership continuously while the transfer plays out, so a
	// leaderless interval is observed rather than inferred from endpoints.
	var (
		samplesMu            sync.Mutex
		sampledTotal         int
		leaderlessSamples    int
		oldLeaderDownSamples int
		firstLeaderlessMs    int64 = -1
		lastLeaderlessMs     int64
	)
	stopSampling := make(chan struct{})
	go func() {
		tick := time.NewTicker(time.Millisecond)
		defer tick.Stop()
		for {
			select {
			case <-stopSampling:
				return
			case <-tick.C:
				ids := assuranceLeaderIDs(nodes)
				ms := time.Since(callAt).Milliseconds()
				samplesMu.Lock()
				sampledTotal++
